contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address x) public payable {
        bool setReverted;
        c.SetLogFile(x); if (__ESBMC_reverted()) return;
        setReverted = false;
        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { initReverted = true; } else { initReverted = false; }
        assert(!setReverted && !initReverted);
    }
    receive() external payable {}
}

